import request from 'supertest';
import { Pool } from 'pg';
import app from '../../index';
import { getPool, connectDatabase } from '../../config/database';
import { createTestUser, createAuthHeader } from '../utils/testHelpers';

describe('Profile Integration Tests', () => {
  let pool: Pool;

  beforeAll(async () => {
    await connectDatabase();
    pool = getPool();
  });

  afterAll(async () => {
    await pool.end();
  });

  beforeEach(async () => {
    // Clean up test data before each test
    await pool.query('DELETE FROM users WHERE email LIKE $1', ['%test%']);
  });

  describe('GET /api/profile', () => {
    it('should get current user profile with valid token', async () => {
      const testUser = await createTestUser();

      const response = await request(app)
        .get('/api/profile')
        .set(createAuthHeader(testUser.accessToken))
        .expect(200);

      expect(response.body.success).toBe(true);
      expect(response.body.data.user).toBeDefined();
      expect(response.body.data.user.id).toBe(testUser.id);
      expect(response.body.data.user.email).toBe(testUser.email);
      expect(response.body.data.user.firstName).toBe(testUser.firstName);
      expect(response.body.data.user.lastName).toBe(testUser.lastName);
    });

    it('should reject request without token', async () => {
      const response = await request(app)
        .get('/api/profile')
        .expect(401);

      expect(response.body.success).toBe(false);
      expect(response.body.error).toContain('requerido');
    });
  });

  describe('PUT /api/profile', () => {
    it('should update user profile successfully', async () => {
      const testUser = await createTestUser();

      const updateData = {
        firstName: 'Carlos',
        lastName: 'González',
        dateOfBirth: '1985-05-15'
      };

      const response = await request(app)
        .put('/api/profile')
        .set(createAuthHeader(testUser.accessToken))
        .send(updateData)
        .expect(200);

      expect(response.body.success).toBe(true);
      expect(response.body.message).toContain('actualizado exitosamente');
      expect(response.body.data.user.firstName).toBe(updateData.firstName);
      expect(response.body.data.user.lastName).toBe(updateData.lastName);
    });

    it('should validate profile data', async () => {
      const testUser = await createTestUser();

      const invalidData = {
        firstName: 'A', // Too short
        lastName: 'B'.repeat(60), // Too long
        dateOfBirth: '2010-01-01' // Too young
      };

      const response = await request(app)
        .put('/api/profile')
        .set(createAuthHeader(testUser.accessToken))
        .send(invalidData)
        .expect(400);

      expect(response.body.success).toBe(false);
      expect(response.body.error).toContain('inválidos');
      expect(response.body.details).toBeDefined();
      expect(response.body.details.length).toBeGreaterThan(0);
    });

    it('should allow partial updates', async () => {
      const testUser = await createTestUser();

      const partialUpdate = {
        firstName: 'UpdatedName'
      };

      const response = await request(app)
        .put('/api/profile')
        .set(createAuthHeader(testUser.accessToken))
        .send(partialUpdate)
        .expect(200);

      expect(response.body.success).toBe(true);
      expect(response.body.data.user.firstName).toBe(partialUpdate.firstName);
      expect(response.body.data.user.lastName).toBe(testUser.lastName); // Should remain unchanged
    });
  });

  describe('POST /api/profile/photo', () => {
    it('should upload profile photo successfully', async () => {
      const testUser = await createTestUser();

      const photoData = {
        photoData: 'data:image/jpeg;base64,',
        fileName: 'profile.jpg'
      };

      const response = await request(app)
        .post('/api/profile/photo')
        .set(createAuthHeader(testUser.accessToken))
        .send(photoData)
        .expect(200);

      expect(response.body.success).toBe(true);
      expect(response.body.message).toContain('actualizada exitosamente');
      expect(response.body.data.photoUrl).toBeDefined();
      expect(response.body.data.photoUrl).toContain(testUser.id);
    });

    it('should reject invalid file types', async () => {
      const testUser = await createTestUser();

      const invalidPhotoData = {
        photoData: 'data:text/plain;base64,SGVsbG8gV29ybGQ=',
        fileName: 'document.txt'
      };

      const response = await request(app)
        .post('/api/profile/photo')
        .set(createAuthHeader(testUser.accessToken))
        .send(invalidPhotoData)
        .expect(400);

      expect(response.body.success).toBe(false);
      expect(response.body.error).toContain('Tipo de archivo no permitido');
    });
  });

  describe('GET /api/profile/:userId', () => {
    it('should get public profile of another user', async () => {
      const testUser = await createTestUser();

      const response = await request(app)
        .get(`/api/profile/${testUser.id}`)
        .expect(200);

      expect(response.body.success).toBe(true);
      expect(response.body.data.user).toBeDefined();
      expect(response.body.data.user.id).toBe(testUser.id);
      expect(response.body.data.user.firstName).toBe(testUser.firstName);
      expect(response.body.data.user.lastName).toBe(testUser.lastName);
      
      // Should not include sensitive information
      expect(response.body.data.user.email).toBeUndefined();
      expect(response.body.data.user.phone).toBeUndefined();
    });

    it('should return 404 for non-existent user', async () => {
      const response = await request(app)
        .get('/api/profile/00000000-0000-0000-0000-000000000000')
        .expect(404);

      expect(response.body.success).toBe(false);
      expect(response.body.error).toContain('no encontrado');
    });
  });

  describe('DELETE /api/profile', () => {
    it('should delete user account with correct password', async () => {
      const testUser = await createTestUser({
        password: 'TestPassword123!'
      });

      const response = await request(app)
        .delete('/api/profile')
        .set(createAuthHeader(testUser.accessToken))
        .send({
          password: 'TestPassword123!'
        })
        .expect(200);

      expect(response.body.success).toBe(true);
      expect(response.body.message).toContain('eliminada exitosamente');

      // Verify user can no longer login
      const loginResponse = await request(app)
        .post('/api/auth/login')
        .send({
          email: testUser.email,
          password: 'TestPassword123!'
        })
        .expect(401);

      expect(loginResponse.body.success).toBe(false);
    });

    it('should reject deletion with incorrect password', async () => {
      const testUser = await createTestUser({
        password: 'TestPassword123!'
      });

      const response = await request(app)
        .delete('/api/profile')
        .set(createAuthHeader(testUser.accessToken))
        .send({
          password: 'WrongPassword123!'
        })
        .expect(401);

      expect(response.body.success).toBe(false);
      expect(response.body.error).toContain('incorrecta');
    });

    it('should require password for account deletion', async () => {
      const testUser = await createTestUser();

      const response = await request(app)
        .delete('/api/profile')
        .set(createAuthHeader(testUser.accessToken))
        .send({})
        .expect(400);

      expect(response.body.success).toBe(false);
      expect(response.body.error).toContain('requerida');
    });
  });
});